package com.realmsoffate.toolkit.ui.creatures;
import com.realmsoffate.toolkit.data.MonsterDataService; import com.realmsoffate.toolkit.project.ModProject; import com.realmsoffate.toolkit.ui.ToolkitColors;
import javax.swing.*; import java.awt.*; import java.io.IOException; import java.util.List;
public class CreaturesPanel extends JPanel { public interface Listener{void onNewMonster();void onOpenMonster(MonsterDataService.MonsterEntry e);} public CreaturesPanel(ModProject p,MonsterDataService s,Listener l){setLayout(new BorderLayout());setBorder(BorderFactory.createEmptyBorder(24,24,24,24));setBackground(ToolkitColors.BACKGROUND);JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JLabel h=new JLabel("Creatures");h.setFont(h.getFont().deriveFont(Font.BOLD,26f));h.setForeground(ToolkitColors.TEXT_PRIMARY);JButton add=new JButton("+ New Monster");add.addActionListener(e->l.onNewMonster());top.add(h,BorderLayout.WEST);top.add(add,BorderLayout.EAST);add(top,BorderLayout.NORTH);JPanel list=new JPanel();list.setOpaque(false);list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));try{List<MonsterDataService.MonsterEntry> es=s.list(p);if(es.isEmpty()){JLabel x=new JLabel("No mod monsters yet. Create one to add monsters.dat to this mod.");x.setForeground(ToolkitColors.TEXT_SECONDARY);list.add(x);}for(MonsterDataService.MonsterEntry me:es){JButton b=new JButton(me.getName()+"   •   "+me.getGroup());b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,42));b.addActionListener(e->l.onOpenMonster(me));list.add(b);list.add(Box.createVerticalStrut(6));}}catch(IOException ex){list.add(new JLabel(ex.getMessage()));}JScrollPane sp=new JScrollPane(list);sp.setBorder(BorderFactory.createEmptyBorder());sp.getVerticalScrollBar().setUnitIncrement(20);add(sp,BorderLayout.CENTER);}}
